-- Migration 0026_staff_support: generated by drizzle-kit (tables, enums, keys, checks), RLS, grants and functions hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #308)
-- Platform staff and consented support sessions (#308, part of #27; spike §4.2, §6; PRD PL-6):
--   * staff_user: global (GLOBAL_TABLES), no RLS. The app and clerk roles may only SELECT it: staff
--     are created and disabled solely by the operator CLI (`pnpm --filter @causedeck/admin
--     staff:add`), which connects as the owner role, so no app or UI path can create staff.
--   * support_session: tenant table under FORCE RLS (tenantPolicy()). Besides ws_isolation, the
--     SELECT-only `staff_self` policy lets an enabled staff member list their own sessions from a
--     user scope (app.user_id pinned, no workspace). A grant lasts at most 240 minutes (CHECK).
--   * app_expire_support_sessions() and app_end_staff_support_sessions(staff) are owner-defined
--     sweeps across workspaces (the expiry job; ending a disabled staff member's sessions). FORCE
--     binds the owner too, so the owner gets narrow read/update policies used only by them. They
--     return ids only.
-- New tables, policies and functions only: nothing existing is altered or dropped.
CREATE TYPE "public"."staff_role" AS ENUM('support', 'ops', 'admin');--> statement-breakpoint
CREATE TYPE "public"."support_session_scope" AS ENUM('metadata', 'view');--> statement-breakpoint
CREATE TYPE "public"."support_session_status" AS ENUM('requested', 'granted', 'denied', 'expired', 'ended');--> statement-breakpoint
CREATE TABLE "staff_user" (
	"user_id" uuid PRIMARY KEY NOT NULL,
	"role" "staff_role" NOT NULL,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"disabled_at" timestamp with time zone
);
--> statement-breakpoint
CREATE TABLE "support_session" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"requested_by_staff" uuid NOT NULL,
	"granted_by_user" uuid,
	"scope" "support_session_scope" DEFAULT 'metadata' NOT NULL,
	"reason" text NOT NULL,
	"status" "support_session_status" DEFAULT 'requested' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"granted_at" timestamp with time zone,
	"expires_at" timestamp with time zone,
	"ended_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "support_session_reason_chk" CHECK (length(btrim(reason)) between 1 and 500),
	CONSTRAINT "support_session_granted_chk" CHECK (status <> 'granted' or (granted_at is not null and expires_at is not null)),
	CONSTRAINT "support_session_window_chk" CHECK (expires_at is null or (granted_at is not null and expires_at > granted_at and expires_at <= granted_at + interval '240 minutes'))
);
--> statement-breakpoint
ALTER TABLE "staff_user" ADD CONSTRAINT "staff_user_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "staff_user" ADD CONSTRAINT "staff_user_created_by_user_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "support_session" ADD CONSTRAINT "support_session_requested_by_staff_user_id_fk" FOREIGN KEY ("requested_by_staff") REFERENCES "public"."user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "support_session" ADD CONSTRAINT "support_session_granted_by_user_user_id_fk" FOREIGN KEY ("granted_by_user") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "support_session" ADD CONSTRAINT "support_session_workspace_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."organization"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "support_session_workspace_id_idx" ON "support_session" USING btree ("workspace_id");--> statement-breakpoint
CREATE INDEX "support_session_workspace_status_idx" ON "support_session" USING btree ("workspace_id","status");--> statement-breakpoint
CREATE INDEX "support_session_staff_status_idx" ON "support_session" USING btree ("requested_by_staff","status");--> statement-breakpoint
ALTER TABLE "support_session" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "support_session" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "ws_isolation" ON "support_session" AS PERMISSIVE FOR ALL TO PUBLIC USING (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "staff_self" ON "support_session" AS PERMISSIVE FOR SELECT TO PUBLIC
  USING (
    nullif(current_setting('app.workspace_id', true), '') IS NULL
    AND requested_by_staff = nullif(current_setting('app.user_id', true), '')::uuid
    AND EXISTS (
      SELECT 1 FROM staff_user s WHERE s.user_id = requested_by_staff AND s.disabled_at IS NULL
    )
  );--> statement-breakpoint
CREATE POLICY "owner_definer_read" ON "support_session" AS PERMISSIVE FOR SELECT TO causedeck_owner
  USING (true);--> statement-breakpoint
CREATE POLICY "owner_definer_sweep" ON "support_session" AS PERMISSIVE FOR UPDATE TO causedeck_owner
  USING (true) WITH CHECK (true);--> statement-breakpoint
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON "staff_user" FROM causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT ON "staff_user" TO causedeck_app, causedeck_clerk;--> statement-breakpoint
CREATE FUNCTION app_expire_support_sessions()
  RETURNS TABLE (id uuid, workspace_id uuid, requested_by_staff uuid)
  LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    UPDATE support_session s
       SET status = 'expired', ended_at = now()
     WHERE s.status = 'granted' AND s.expires_at <= now()
    RETURNING s.id, s.workspace_id, s.requested_by_staff
  $$;--> statement-breakpoint
CREATE FUNCTION app_end_staff_support_sessions(staff uuid)
  RETURNS TABLE (id uuid, workspace_id uuid, requested_by_staff uuid, was_granted boolean)
  LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    WITH ended AS (
      UPDATE support_session s
         SET status = 'ended', ended_at = now()
        FROM (SELECT o.id, o.status FROM support_session o
               WHERE o.requested_by_staff = staff AND o.status IN ('requested', 'granted')
               FOR UPDATE) prev
       WHERE s.id = prev.id
      RETURNING s.id, s.workspace_id, s.requested_by_staff, prev.status = 'granted' AS was_granted
    )
    SELECT * FROM ended
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_expire_support_sessions(), app_end_staff_support_sessions(uuid) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_expire_support_sessions(), app_end_staff_support_sessions(uuid) TO causedeck_app, causedeck_clerk;
